import React, { useState, useEffect } from 'react';
import { api } from '../api';
import TaskList from '../components/TaskList';
import TaskForm from '../components/TaskForm';

export default function Dashboard({ auth }){
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [editing, setEditing] = useState(null);
  const [filterProgress, setFilterProgress] = useState('');
  const [dueFilter, setDueFilter] = useState(''); // week|overdue

  useEffect(()=> { fetchTasks(); }, [filterProgress, dueFilter]);

  async function fetchTasks(){
    setLoading(true); setError(null);
    try {
      const qs = {};
      if (filterProgress) qs.progress = filterProgress;
      if (dueFilter) qs.due = dueFilter;
      const res = await api('/tasks', { token: auth.token, qs });
      setTasks(res.data);
    } catch (e) { setError(e.message || JSON.stringify(e)); }
    setLoading(false);
  }

  const createTask = async (payload) => {
    try {
      const res = await api('/tasks', { method: 'POST', token: auth.token, body: payload });
      setTasks(prev => [res.data, ...prev]);
    } catch (e) { alert(e.message || JSON.stringify(e)); }
  };

  const updateTask = async (id, payload) => {
    try {
      const res = await api(`/tasks/${id}`, { method: 'PUT', token: auth.token, body: payload });
      setTasks(prev => prev.map(t => t._id === id ? res.data : t));
      setEditing(null);
    } catch (e) { alert(e.message || JSON.stringify(e)); }
  };

  const deleteTask = async (id) => {
    if (!window.confirm('Delete this task?')) return;
    try {
      await api(`/tasks/${id}`, { method: 'DELETE', token: auth.token });
      setTasks(prev => prev.filter(t => t._id !== id));
    } catch (e) { alert(e.message || JSON.stringify(e)); }
  };

  const handleSave = (payload) => {
    if (editing) {
      updateTask(editing._id, payload);
    } else {
      createTask(payload);
    }
  };

  return (
    <div>
      <h3>Dashboard</h3>
      <div>
        {/* Filter Container: Clean, white background for readability */}
        <div style={{ 
          marginBottom: 20, 
          padding: 15, 
          border: '1px solid #E3E9F0', 
          borderRadius: '8px', 
          backgroundColor: '#F7FBFF', /* Very light blue background for contrast */
          display: 'flex', 
          gap: '20px', 
          alignItems: 'center' 
        }}>
          <div>
            <label style={{ marginRight: 8, fontWeight: '600', color: '#1A2E35' }}>Filter by progress:</label>
            <select value={filterProgress} onChange={e=>setFilterProgress(e.target.value)} style={{ width: 'auto', display: 'inline-block' }}>
              <option value="">(all)</option>
              <option value="not-started">not-started</option>
              <option value="in-progress">in-progress</option>
              <option value="completed">completed</option>
            </select>
          </div>

          <div>
            <label style={{ marginRight: 8, fontWeight: '600', color: '#1A2E35' }}>Due filter:</label>
            <select value={dueFilter} onChange={e=>setDueFilter(e.target.value)} style={{ width: 'auto', display: 'inline-block' }}>
              <option value="">(all)</option>
              <option value="week">Due this week</option>
              <option value="overdue">Overdue</option>
            </select>
          </div>
          {editing && <button onClick={() => setEditing(null)} style={{ marginLeft: 'auto', backgroundColor: '#E57373', color: 'white' }}>Cancel Edit</button>}
        </div>

        {/* TaskForm component: Now acts as both Create and Edit form */}
        <div style={{ marginBottom: 25, padding: 15, border: '1px solid #C5D4E1', borderRadius: '8px', backgroundColor: '#F0F4F8' }}>
          <h4 style={{ color: '#38C7D5' }}>{editing ? 'Edit Task' : 'Create New Task'}</h4>
          <TaskForm 
            auth={auth} 
            initial={editing||{}} 
            onSave={async (payload)=>{ await handleSave(payload); }} 
          />
        </div>


        {loading ? <div style={{ color: '#4A6C80' }}>Loading...</div> : (
          <>
            {error && <div style={{ color: '#D32F2F', padding: 10, border: '1px solid #D32F2F', borderRadius: '4px' }}>Error: {error}</div>}
            <TaskList tasks={tasks} onEdit={(t)=>setEditing(t)} onDelete={deleteTask} auth={auth} />
          </>
        )}
      </div>
    </div>
  );
}
